"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Minimal Freesound API client for step 0 item 7 (P1 v0.3). Never prints a key, token or account detail.

Credentials live outside the project: ~/freesound_env.json (client id, API key, redirect URI) and
~/freesound_oauth.json (access and refresh tokens, written by scripts/freesound_authorize.py). The access token is
refreshed automatically when it is about to expire.

  python -I scripts/freesound_client.py check      # field names, token expiry, one search, one OAuth call,
                                                   # and a 100-byte ranged download of one original file
"""
import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

ENV = os.path.join(os.path.expanduser("~"), "freesound_env.json")
TOK = os.path.join(os.path.expanduser("~"), "freesound_oauth.json")
API = "https://freesound.org/apiv2"


def env():
    return json.load(open(ENV, encoding="utf-8-sig"))


def tokens():
    t = json.load(open(TOK, encoding="utf-8"))
    if time.time() > t.get("expires_at", 0) - 300:
        body = urllib.parse.urlencode({"client_id": t.get("client_id") or env()["FREESOUND_CLIENT_ID"],
                                       "grant_type": "refresh_token",
                                       "refresh_token": t["refresh_token"]}).encode("ascii")
        with urllib.request.urlopen(urllib.request.Request(f"{API}/oauth2/access_token/", data=body), timeout=30) as r:
            new = json.loads(r.read().decode("utf-8"))
        new["expires_at"] = time.time() + float(new.get("expires_in", 86400)) - 60
        new["client_id"] = t.get("client_id")
        json.dump(new, open(TOK, "w", encoding="utf-8"))
        t = new
    return t


def get(path, oauth=False, params=None, headers=None, raw=False):
    auth = f"Bearer {tokens()['access_token']}" if oauth else f"Token {str(env()['FREESOUND_API_KEY']).strip()}"
    url = path if path.startswith("http") else f"{API}{path}"
    if params:
        url += "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"Authorization": auth, **(headers or {})})
    with urllib.request.urlopen(req, timeout=120) as r:
        data = r.read()
        return (r.status, data) if raw else (r.status, json.loads(data.decode("utf-8")))


def check():
    e = env()
    print("env fields:", sorted(e), "| lengths:", {k: len(str(v)) for k, v in e.items()})
    t = json.load(open(TOK, encoding="utf-8"))
    print("token fields:", sorted(k for k in t if k != "client_id"),
          "| expires:", time.strftime("%Y-%m-%d %H:%M", time.localtime(t.get("expires_at", 0))))
    st, js = get("/search/", params={"query": "doorbell", "filter": 'license:"Creative Commons 0"',
                                     "fields": "id,name,license,created", "page_size": 3, "sort": "created_desc"})
    print("token-auth search:", st, "| CC0 doorbell results:", js.get("count"))
    sid = js["results"][0]["id"]
    try:
        st, _ = get("/me/", oauth=True)
        print("OAuth call (/me/):", st)
    except urllib.error.HTTPError as ex:
        print("OAuth call (/me/) failed:", ex.code)
    try:
        st, data = get(f"/sounds/{sid}/download/", oauth=True, headers={"Range": "bytes=0-99"}, raw=True)
        print("original download (first 100 bytes):", st, "| bytes:", len(data))
    except urllib.error.HTTPError as ex:
        print("original download failed:", ex.code)


if __name__ == "__main__" and sys.argv[1:] == ["check"]:
    check()
